#include <stdio.h>

/* Euclid's algorithm: gcd(a, b) = gcd(b, a % b), gcd(a, 0) = a */
int gcd(int a, int b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

int main(void) {
    int num1, num2;
    printf("Enter two positive integers: ");
    if (scanf("%d %d", &num1, &num2) != 2 || num1 <= 0 || num2 <= 0) {
        printf("Invalid input\n");
        return 1;
    }
    printf("GCD of %d and %d = %d\n", num1, num2, gcd(num1, num2));
    return 0;
}

