Program (compiled and run with gcc):
#include <stdio.h>
int main(void) {
    FILE *fp = fopen("students.txt", "r");
    if (fp == NULL) { perror("students.txt"); return 1; }
    int id, m1, m2, m3, m4;
    char name[30];
    printf("ID    Name    Total Avg   Grade\n");
    while (fscanf(fp, "%d %29s %d %d %d %d", &id, name, &m1, &m2, &m3, &m4) == 6) {
        int total = m1 + m2 + m3 + m4;
        double avg = total / 4.0;
        char grade;
        if (avg >= 80) grade = 'A';
        else if (avg >= 70) grade = 'B';
        else if (avg >= 60) grade = 'C';
        else if (avg >= 50) grade = 'D';
        else grade = 'F';
        printf("%-5d %-7s %-5d %.2f %c\n", id, name, total, avg, grade);
    }
    fclose(fp);
    return 0;
}

For the sample file:
101 Rahim 80 70 60 50
102 Karim 90 85 88 92
103 Nila 45 55 65 40

Actual program output (verified):
